  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gray-500);
  padding-bottom: 12px;
  border-bottom: 2px solid var(--gray-200);
}
.donate-table td {
  padding: 14px 0;
  font-size: 15px;
  border-bottom: 1px solid var(--gray-100);
  line-height: 1.5;
}
.donate-table td:first-child { font-family: var(--heading); font-weight: 600; color: var(--navy); width: 80px; }
.donate-table tr:last-child td { border-bottom: none; font-family: var(--body); font-weight: 500; color: var(--gray-500); font-style: italic; }

@media (max-width: 768px) {
  .donate-grid { grid-template-columns: 1fr; gap: 32px; }
  .donate-amounts { grid-template-columns: repeat(2, 1fr); }
}

/* ========== FOOTER ========== */
.footer {
  background: var(--gray-900);
  color: rgba(255,255,255,0.55);
  padding: 72px 0 32px;
}
.footer-grid { display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 40px; margin-bottom: 56px; }

.footer-brand .logo { color: var(--white); font-size: 22px; margin-bottom: 16px; }
.footer-brand p { font-size: 14px; line-height: 1.7; margin-bottom: 20px; max-width: 260px; }
.footer-social { display: flex; gap: 12px; }
.footer-social a {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
  color: rgba(255,255,255,0.5);
}
.footer-social a:hover { background: var(--red); color: var(--white); }
.footer-social a svg { width: 16px; height: 16px; }

.footer-col h4 {
  font-family: var(--heading);
  font-size: 14px;
  font-weight: 600;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 20px;
}
.footer-col a {
  display: block;
  color: rgba(255,255,255,0.5);
  text-decoration: none;
  font-size: 14px;
  padding: 5px 0;
  transition: color 0.2s;
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
}
.footer-bottom span { color: rgba(255,255,255,0.35); }

@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 600px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ========== DONATE MODAL ========== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(26,24,22,0.6);
  backdrop-filter: blur(4px);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
}
.modal-overlay.active { opacity: 1; pointer-events: auto; }

.modal {
  background: var(--white);
  border-radius: 16px;
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
  transform: translateY(20px) scale(0.97);
  transition: transform 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.modal-overlay.active .modal { transform: translateY(0) scale(1); }

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 28px;
  border-bottom: 1px solid var(--gray-200);
}
.modal-header h2 { font-size: 22px; }
.modal-close {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: none;
  background: var(--gray-100);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  color: var(--gray-500);
}
.modal-close:hover { background: var(--gray-200); color: var(--gray-900); }
.modal-close svg { width: 18px; height: 18px; }

.modal-body { padding: 28px; }

.modal-amounts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 20px; }
@media (max-width: 400px) { .modal-amounts { grid-template-columns: repeat(2, 1fr); } }

.modal-amount-btn {
  padding: 16px 10px;
  background: var(--gray-50);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-family: var(--heading);
  font-size: 16px;
  font-weight: 600;
  color: var(--gray-900);
  transition: all 0.25s;
}
.modal-amount-btn:hover { border-color: var(--red); background: var(--red-light); }
.modal-amount-btn.selected { border-color: var(--red); background: var(--red-light); color: var(--red); }
.modal-amount-btn small { display: block; font-family: var(--body); font-size: 11px; color: var(--gray-500); font-weight: 400; margin-top: 3px; }
.modal-amount-btn.selected small { color: var(--red); }

.modal-summary {
  background: var(--navy);
  color: var(--white);
  border-radius: var(--radius-sm);
  padding: 20px;
  margin-bottom: 20px;
}
.modal-summary p { font-size: 14px; color: rgba(255,255,255,0.65); line-height: 1.6; }
.modal-summary strong { color: var(--white); font-family: var(--heading); }

.modal .btn { width: 100%; font-size: 16px; padding: 16px; }

/* ========== UTILITY ANIMATIONS ========== */
.fade-up {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.fade-up.visible { opacity: 1; transform: translateY(0); }

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}
</style>
</head>
