<script>
'use strict';

// ========== HEADER SCROLL ==========
const header = document.getElementById('header');
let scrollTicking = false;
window.addEventListener('scroll', () => {
  if (!scrollTicking) {
    requestAnimationFrame(() => {
      header.classList.toggle('scrolled', window.scrollY > 10);
      scrollTicking = false;
    });
    scrollTicking = true;
  }
});

// ========== MOBILE MENU ==========
const hamburger = document.getElementById('hamburger');
const mobileNav = document.getElementById('mobileNav');

hamburger.addEventListener('click', () => {
  const isActive = mobileNav.classList.toggle('active');
  hamburger.classList.toggle('active');
  hamburger.setAttribute('aria-expanded', isActive);
  document.body.style.overflow = isActive ? 'hidden' : '';
});

function closeMobileMenu() {
  mobileNav.classList.remove('active');
  hamburger.classList.remove('active');
  hamburger.setAttribute('aria-expanded', 'false');
  document.body.style.overflow = '';
}

// Close mobile menu on Escape
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    closeMobileMenu();
    closeDonateModal();
  }
});

// ========== ANIMATED COUNTERS ==========
function animateCounters() {
  document.querySelectorAll('.counter').forEach(el => {
    if (el.dataset.animated) return;
    const target = parseFloat(el.dataset.target);
    const prefix = el.dataset.prefix || '';
    const suffix = el.dataset.suffix || '';
    const decimals = parseInt(el.dataset.decimals || '0');
    const format = el.dataset.format;
    const duration = 2000;
    const startTime = performance.now();

    el.dataset.animated = 'true';

    function update(now) {
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      const current = target * eased;

      let display;
      if (format === 'comma') {
        display = Math.floor(current).toLocaleString();
      } else {
        display = current.toFixed(decimals);
      }

      el.textContent = prefix + display + suffix;

      if (progress < 1) {
        requestAnimationFrame(update);
      } else {
        if (format === 'comma') {
          el.textContent = prefix + target.toLocaleString() + suffix;
        } else {
          el.textContent = prefix + target.toFixed(decimals) + suffix;
        }
      }
    }

    requestAnimationFrame(update);
  });
}

// ========== INTERSECTION OBSERVER ==========
const observerOptions = { threshold: 0.2, rootMargin: '0px 0px -40px 0px' };

const impactObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      animateCounters();
      impactObserver.unobserve(entry.target);
    }
  });
}, observerOptions);

const impactSection = document.getElementById('impact');
if (impactSection) impactObserver.observe(impactSection);

// Fade-up animations
const fadeObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
    }
  });
}, { threshold: 0.1, rootMargin: '0px 0px -30px 0px' });

// ========== PROGRAM ACCORDION ==========
document.querySelectorAll('.accordion-trigger').forEach(trigger => {
  trigger.addEventListener('click', () => {
    const item = trigger.parentElement;
    const body = item.querySelector('.accordion-body');
    const isActive = item.classList.contains('active');

    // Close all
    document.querySelectorAll('.accordion-item').forEach(other => {
      other.classList.remove('active');
      other.querySelector('.accordion-body').style.maxHeight = '0';
      other.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
    });

    // Toggle clicked
    if (!isActive) {
      item.classList.add('active');
      body.style.maxHeight = body.scrollHeight + 'px';
      trigger.setAttribute('aria-expanded', 'true');
    }
  });
});

// ========== DONATE AMOUNT SELECTION (INLINE) ==========
function selectAmount(btn, amount, impact) {
  document.querySelectorAll('.donate-amount-btn').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
  document.getElementById('donateImpact').innerHTML =
    '<p>Your gift of <strong>$' + amount + '</strong> — ' + impact + '.</p>';
}

// ========== DONATE MODAL ==========
let modalAmount = 25;
let modalImpact = 'Provides 5 emergency blankets for displaced families';

function openDonateModal() {
  document.getElementById('donateModal').classList.add('active');
  document.body.style.overflow = 'hidden';
  // Reset modal to default
  modalAmount = 25;
  modalImpact = 'Provides 5 emergency blankets for displaced families';
  document.querySelectorAll('[data-modal-amount]').forEach(b => b.classList.remove('selected'));
  const defaultBtn = document.querySelector('[data-modal-amount="25"]');
  if (defaultBtn) defaultBtn.classList.add('selected');
  updateModalImpact();
}

function closeDonateModal() {
  document.getElementById('donateModal').classList.remove('active');
  document.body.style.overflow = '';
}

function selectModalAmount(btn, amount, impact) {
  document.querySelectorAll('[data-modal-amount]').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
  modalAmount = amount;
  modalImpact = impact;
  updateModalImpact();
}

function updateModalImpact() {
  document.getElementById('modalImpact').innerHTML =
    '<p>Your gift of <strong>$' + modalAmount + '</strong> — <strong>' + modalImpact + '</strong>.</p>';
}

// Close modal on overlay click
document.getElementById('donateModal').addEventListener('click', function(e) {
  if (e.target === this) closeDonateModal();
});

// ========== NEWS CAROUSEL ==========
(function() {
  const track = document.getElementById('newsTrack');
  const prevBtn = document.getElementById('carouselPrev');
  const nextBtn = document.getElementById('carouselNext');
  const slides = track.querySelectorAll('.news-slide');
  let currentSlide = 0;
  const totalSlides = slides.length;

  function updateCarousel() {
    track.style.transform = 'translateX(-' + (currentSlide * 100) + '%)';
    prevBtn.disabled = currentSlide === 0;
    nextBtn.disabled = currentSlide === totalSlides - 1;
  }

  prevBtn.addEventListener('click', () => {
    if (currentSlide > 0) { currentSlide--; updateCarousel(); }
  });

  nextBtn.addEventListener('click', () => {
    if (currentSlide < totalSlides - 1) { currentSlide++; updateCarousel(); }
  });

  // Touch support
  let touchStartX = 0;
  let touchEndX = 0;

  track.addEventListener('touchstart', (e) => { touchStartX = e.changedTouches[0].screenX; }, { passive: true });
  track.addEventListener('touchend', (e) => {
    touchEndX = e.changedTouches[0].screenX;
    const diff = touchStartX - touchEndX;
    if (Math.abs(diff) > 50) {
      if (diff > 0 && currentSlide < totalSlides - 1) { currentSlide++; }
      else if (diff < 0 && currentSlide > 0) { currentSlide--; }
      updateCarousel();
    }
  });

  updateCarousel();
})();

// Initialize first accordion item
document.querySelector('.accordion-item.active .accordion-body').style.maxHeight =
  document.querySelector('.accordion-item.active .accordion-body').scrollHeight + 'px';
</script>
</body>
</html>
